const nz=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\s+/g,'');
let QON=false,qbuilt=false;
function buildQ(){if(qbuilt)return;qbuilt=true;const f=document.createDocumentFragment();QD.forEach(q=>{const d=el('div',{className:'q'});d.style.cssText=`left:${q[2]/W*100}%;top:${q[3]/H*100}%;--a:${q[4]}deg`;f.append(d)});st.append(f)}
$('#zq').onclick=()=>{QON=!QON;buildQ();st.classList.toggle('qon',QON);$('#zq').setAttribute('aria-pressed',QON)};
function clearMk(){st.querySelectorAll('.mk').forEach(e=>e.remove())}
card.querySelector('.x').addEventListener('click',clearMk);
function mark(list,w,h){clearMk();list.forEach(([x,y,a])=>{const d=el('div',{className:'mk'});d.style.cssText=`left:${x/W*100}%;top:${y/H*100}%;width:${w}px;height:${h}px;margin:${-h/2}px 0 0 ${-w/2}px;--a:${a}deg`;st.append(d)})}
function info(t,tag,col,txt,x,y){cur={x,y};pins.forEach(b=>b.classList.remove('on'));card.style.setProperty('--c',col);card.querySelector('.tag').textContent=tag;card.querySelector('h2').textContent=t;card.querySelector('p').textContent=txt;$('#lk').hidden=true;curP=null;updFv();showSt(null);card.classList.add('show')}
const SET={NO:'Noroeste',NE:'Nordeste',SO:'Sudoeste',SE:'Sudeste'};
function selQ(q,go){const z=SET[q[1].replace(/\s?\d+$/,'').slice(-2)];mark([[q[2],q[3],q[4]]],46,26);info('Quadra '+q[0],'Quadra','#3b6ea5',(q[1]?'Sigla: '+q[1]:'Sem sigla no mapa')+(z?' · Setor '+z:''),q[2],q[3]);if(go)focus({x:q[2],y:q[3]},4)}
function avTxt(n){let m;if(m=n.match(/^Av\. NS (\w+)/))return'Avenida NS '+m[1]+' (eixo norte–sul), indicada no mapa.';if(m=n.match(/^Av\. LO (\w+)/))return'Avenida LO '+m[1]+' (eixo leste–oeste), indicada no mapa.';if(n=='Av. JK')return'Avenida Juscelino Kubitschek, indicada no mapa.';if(/^TO-/.test(n))return'Rodovia estadual '+n+', indicada no mapa.';return'Avenida indicada em vários trechos do mapa.'}
function selAv(n,go){const L=AVD.filter(a=>a[0]==n);mark(L.map(a=>[a[1],a[2],a[3]]),70,16);info(n,/^TO-/.test(n)?'Rodovia':'Avenida','#5a8f2e',avTxt(n),L[0][1],L[0][2]);if(go)focus({x:L[0][1],y:L[0][2]},3)}
function closeCard(){if(card.classList.contains('show'))card.querySelector('.x').click()}
vp.addEventListener('click',e=>{if(ADM||placing||moved>5||e.target.closest('#card,#zoom,#tbar,#rot,#toast,#sbt'))return;if(!QON){closeCard();return}const r=vp.getBoundingClientRect(),x=(e.clientX-r.left-X)/S,y=(e.clientY-r.top-Y)/S;let b=null,bd=1e9;
QD.forEach(q=>{const a=q[4]*Math.PI/180,dx=x-q[2],dy=y-q[3],u=dx*Math.cos(a)+dy*Math.sin(a),v=-dx*Math.sin(a)+dy*Math.cos(a);if(Math.abs(u)<=23&&Math.abs(v)<=13){const d=dx*dx+dy*dy;if(d<bd){bd=d;b=q}}});if(b)selQ(b);else closeCard()});
const _sel=sel;let stepping=false;sel=p=>{clearMk();_sel(p);curP=p;updFv();showSt(p);if(ton&&!stepping){tp=true;clearTimeout(tt);$('#tpause').textContent='▶'}};
const _render=render;render=()=>{_render();hits();nowUI()};
function hits(){const l=$('#list'),t=nz(qs);if(t.length<2)return;const A=QD.filter(q=>nz(q[0]+q[1]).includes(t)).slice(0,30),B=[...new Set(AVD.map(a=>a[0]))].filter(n=>nz(n).includes(t)).slice(0,12);if(!A.length&&!B.length)return;
const h=el('li',{textContent:'Quadras e avenidas'});h.style.cssText='font-size:12px;color:var(--mu);padding:8px 8px 2px';l.append(h);
const add=(txt,sub,fn)=>{const li=el('li'),b=el('button',{className:'it'},el('i',{className:'dot'}),el('span',{},txt,el('small',{textContent:sub})));b.style.setProperty('--c','#8aa4bf');b.onclick=fn;li.append(b);l.append(li)};
A.forEach(q=>add('Quadra '+q[0],q[1],()=>selQ(q,true)));B.forEach(n=>add(n,/^TO-/.test(n)?'Rodovia':'Avenida',()=>selAv(n,true)))}
/* ===== FASE 1: TOUR GUIADO, ROTEIRO (FAVORITOS) E HORA DO DIA ===== */
const FK='palmas-map-fav-v1';let FAV=[],curP=null,tl=[],ti=0,tt=null,tp=false,ton=false;try{FAV=JSON.parse(localStorage.getItem(FK))||[]}catch(e){}
FAV=FAV.filter(n=>P.some(p=>p.n==n));
const saveFav=()=>{try{localStorage.setItem(FK,JSON.stringify(FAV))}catch(e){}};
function toast(m){const x=$('#toast');x.textContent=m;x.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>x.hidden=true,2800)}
function updFv(){const b=$('#fv');if(!curP||!curP.n){b.hidden=true;return}b.hidden=false;const on=FAV.includes(curP.n);b.textContent=on?'♥ No roteiro':'♡ Adicionar ao roteiro';b.setAttribute('aria-pressed',on)}
function countFav(){$('#rotb').textContent='♥ Roteiro'+(FAV.length?' ('+FAV.length+')':'')}
function toggleFav(n){const i=FAV.indexOf(n);i<0?FAV.push(n):FAV.splice(i,1);saveFav();updFv();countFav();render();if(!$('#rot').hidden)rotUI()}
$('#fv').onclick=()=>curP&&toggleFav(curP.n);
const favPlaces=()=>FAV.map(n=>P.find(p=>p.n==n)).filter(Boolean);
function rotText(){const u=CFG.shareUrl||location.href.split('#')[0];return '🗺️ Meu roteiro em Palmas-TO\n'+favPlaces().map((p,i)=>(i+1)+'. '+p.n).join('\n')+'\n\nVeja no mapa: '+u}
function shareWA(){el('a',{href:'https://wa.me/?text='+encodeURIComponent(rotText()),target:'_blank',rel:'noopener'}).click()}
function copyTxt(){const s=rotText(),ok=()=>toast('Roteiro copiado!'),fb=()=>{const a=el('textarea',{value:s});document.body.append(a);a.select();try{document.execCommand('copy');ok()}catch(e){toast('Não foi possível copiar')}a.remove()};
(navigator.clipboard?navigator.clipboard.writeText(s):Promise.reject()).then(ok).catch(fb)}
function mv(i,d){const j=i+d;if(j<0||j>=FAV.length)return;[FAV[i],FAV[j]]=[FAV[j],FAV[i]];saveFav();rotUI()}
function rotUI(){const r=$('#rot');r.innerHTML='';FAV=FAV.filter(n=>P.some(p=>p.n==n));const L=favPlaces();
r.append(el('div',{className:'rh'},el('b',{textContent:'♥ Meu roteiro'}),el('button',{className:'sm',textContent:'✕',title:'Fechar',onclick:()=>r.hidden=true})));
if(!L.length){r.append(el('p',{textContent:'Seu roteiro está vazio. Abra um local no mapa e toque em “Adicionar ao roteiro”.'}));return}
const ol=el('ol');L.forEach((p,i)=>{const li=el('li');li.append(el('span',{textContent:p.n}),el('span',{className:'ra'},el('button',{className:'sm',textContent:'↑',disabled:i==0,onclick:()=>mv(i,-1)}),el('button',{className:'sm',textContent:'↓',disabled:i==L.length-1,onclick:()=>mv(i,1)}),el('button',{className:'sm',textContent:'✕',title:'Remover',onclick:()=>toggleFav(p.n)})));ol.append(li)});
r.append(ol,el('div',{className:'rb'},el('button',{className:'primary',textContent:'▶ Tour do meu roteiro',onclick:()=>{r.hidden=true;startTour(L)}}),el('button',{textContent:'WhatsApp',onclick:shareWA}),el('button',{textContent:'Copiar',onclick:copyTxt}),el('button',{className:'danger',textContent:'Limpar',onclick:()=>{if(confirm('Limpar o roteiro?')){FAV=[];saveFav();countFav();render();rotUI()}}})))}
$('#rotb').onclick=()=>{const r=$('#rot');if(r.hidden){rotUI();r.hidden=false}else r.hidden=true};
/* tour */
const TOUR=['Mirante da Serra','Serra do Lajeado','Taquaruçu (Distrito)','Parque Cesamar','Centro de Convenções Arnaud Rodrigues','Palacinho da Cultura','Praia da Graciosa','Praia do Prata','Ponte da Amizade','Ilha Canela','Lago de Palmas','Praia das Arnos','Praia do Caju','Praia dos Buritis','Kartódromo Rubens Barrichello','Estádio Nilton Santos','Rodoviária','Aeroporto'];
function defTour(){const ok=p=>!p.hide&&!p.notour,a=TOUR.map(n=>P.find(p=>p.n==n)).filter(p=>p&&ok(p));return a.concat(P.filter(p=>ok(p)&&!a.includes(p)&&p.c!='cidades'))}
function arm(){clearTimeout(tt);if(ton&&!tp)tt=setTimeout(()=>ti<tl.length-1?step(ti+1):endTour(true),9000)}
function step(i){ti=clamp(i,0,tl.length-1);const p=tl[ti];clearTimeout(tt);stepping=true;st.style.transition='transform 1.3s cubic-bezier(.4,0,.2,1)';sel(p);focus(p,2.6);stepping=false;setTimeout(()=>{st.style.transition=''},1450);
$('#tinfo').textContent=(ti+1)+'/'+tl.length+' · '+p.n;$('#tpause').textContent=tp?'▶':'⏸';arm()}
function startTour(list){tl=list&&list.length?list:defTour();if(!tl.length)return toast('Nenhum local no tour.');ton=true;tp=false;$('#rot').hidden=true;$('#tbar').hidden=false;$('#tour').textContent='■ Parar tour';step(0)}
function endTour(done){clearTimeout(tt);ton=false;$('#tbar').hidden=true;$('#tour').textContent='▶ Tour guiado';if(done){card.querySelector('.x').click();reset();toast('Tour concluído! Toque em ♡ nos locais para montar seu roteiro.')}}
$('#tour').onclick=()=>ton?endTour(false):startTour();$('#tstop').onclick=()=>endTour(false);
$('#tprev').onclick=()=>step(ti-1);$('#tnext').onclick=()=>ti<tl.length-1?step(ti+1):endTour(true);
$('#tpause').onclick=()=>{tp=!tp;$('#tpause').textContent=tp?'▶':'⏸';arm()};
addEventListener('keydown',e=>{if(ton&&e.key=='Escape')endTour(false)});
/* hora do dia */
const TM={dia:['','☀','Dia'],tarde:['linear-gradient(180deg,rgb(255,232,196),rgb(255,196,146))','🌅','Fim de tarde'],anoitecer:['linear-gradient(180deg,rgb(214,170,205),rgb(240,170,150))','🌆','Anoitecer'],noite:['linear-gradient(180deg,rgb(105,125,190),rgb(70,88,150))','🌙','Noite']};let tmMode='auto';
function autoMode(){const d=new Date(),m=d.getHours()*60+d.getMinutes();return m>=1130||m<320?'noite':m>=1070?'anoitecer':m>=990?'tarde':m<380?'anoitecer':'dia'}
const TMD={tarde:['#ffe8c4','#ffc492',100],anoitecer:['#d6aacd','#f0aa96',100],noite:['#697dbe','#465896',100]};
