Object.keys(nm).forEach(k=>{const w=el('div',{className:'f'});w.style.cssText='border:1px solid var(--bd);border-radius:10px;padding:10px;gap:8px';w.append(el('b',{textContent:nm[k]}),el('div',{className:'row'},fld('Cor do topo','color',()=>g(k,0),v=>s(k,0,v)),fld('Cor da base','color',()=>g(k,1),v=>s(k,1,v))),fld('Intensidade','range',()=>g(k,2),v=>s(k,2,v),[0,140,5]),el('button',{className:'sm',textContent:'Ver esta fase no mapa',onclick:()=>{tmMode=k;applyTm()}}));out.push(w)});
