function applyTm(){const k=tmMode=='auto'?autoMode():tmMode,v=TM[k],b=$('#zt');$('#tint').style.background=k=='dia'?'transparent':grad(k);b.textContent=v[1];b.title='Hora do dia: '+(tmMode=='auto'?'automático ('+v[2]+')':v[2])+' — clique para alterar';b.setAttribute('aria-label',b.title)}
$('#zt').onclick=()=>{const o=['auto','dia','tarde','anoitecer','noite'];tmMode=o[(o.indexOf(tmMode)+1)%o.length];applyTm();toast(tmMode=='auto'?'Hora do dia: automático':'Hora do dia: '+TM[tmMode][2])};
