/* ===== FASE 3: O QUE FAZER AGORA (marcadores) E ABERTO AGORA (horários) ===== */
const DEFTAGS=[{k:'criancas',n:'Com crianças',i:'👨‍👩‍👧'},{k:'porsol',n:'Pôr do sol',i:'🌅'},{k:'gratis',n:'Grátis',i:'🆓'}];
