let openOnly=false;const actTags=new Set();
const fmtm=m=>String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0'),hm=s=>{const a=s.split(':').map(Number);return a[0]*60+a[1]};
function nowP(){const f=new Intl.DateTimeFormat('en-US',{timeZone:'America/Araguaina',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date()),g=k=>f.find(x=>x.type==k).value;return{d:{Sun:0,Mon:1,Tue:2,Wed:3,Thu:4,Fri:5,Sat:6}[g('weekday')],m:(+g('hour')%24)*60+(+g('minute'))}}
function stat(p){const h=p.hours;if(!h)return null;if(h.always)return{open:true,txt:'Aberto 24 horas'};const n=nowP(),slot=i=>{const v=h.d&&h.d[i];if(!v)return null;const a=v.split('-');return[hm(a[0]),hm(a[1])]};
const s=slot(n.d);if(s){if(s[0]<s[1]&&n.m>=s[0]&&n.m<s[1])return{open:true,txt:'Aberto agora · fecha às '+fmtm(s[1])};if(s[0]>s[1]&&n.m>=s[0])return{open:true,txt:'Aberto agora · fecha às '+fmtm(s[1])}}
const y=slot((n.d+6)%7);if(y&&y[0]>y[1]&&n.m<y[1])return{open:true,txt:'Aberto agora · fecha às '+fmtm(y[1])};
for(let k=0;k<8;k++){const i=(n.d+k)%7,x=slot(i);if(!x||x[0]==x[1])continue;if(k==0&&x[0]<=n.m)continue;return{open:false,txt:'Fechado · abre '+(k==0?'hoje':k==1?'amanhã':DN[i])+' às '+fmtm(x[0])}}return{open:false,txt:'Fechado'}}
