if(!CFG.mig15){CFG.mig15=1;P.forEach(p=>{if(p.n=='Praia da Graciosa'&&!p.tags)p.tags=['porsol'];if(p.n=='Parque Cesamar'&&!p.tags)p.tags=['criancas']});save()}
/* ===== MOVIMENTO SUAVE AO CLICAR NOS PINOS ===== */
let prevView=null,flying=false,movedAfter=false;
const _apply=apply;apply=()=>{if(!flying)movedAfter=true;_apply()};
function glide(S2,X2,Y2,ms){flying=true;if(matchMedia('(prefers-reduced-motion: reduce)').matches)ms=0;st.style.transition=ms?`transform ${ms}ms cubic-bezier(.4,0,.2,1)`:'';S=S2;X=X2;Y=Y2;bound();apply();flying=false;movedAfter=false;if(ms)setTimeout(()=>{st.style.transition=''},ms+60)}
function pinFly(p,pv){if(ADM||ton||!p||!p.n)return;if(!prevView)prevView=pv;const S2=S<fit*2?fit*2.6:S;glide(S2,vp.clientWidth/2-p.x*S2,vp.clientHeight*.42-p.y*S2,700)}
function backView(){const v=prevView;prevView=null;if(!v||movedAfter||ADM)return;glide(v.S,v.X,v.Y,700)}
card.querySelector('.x').addEventListener('click',backView);
